% analyze_results_section_aux.m
% Auxiliary descriptive analysis for the revised CLIPS/CV Results section.
%
% PURPOSE
%   Produce compact, machine-readable summaries needed to write the revised
%   Results section without duplicating the inferential analyses already
%   generated by the main DCTA analysis pipeline.
%
% THIS SCRIPT DOES NOT:
%   - rerun simulations,
%   - modify raw/source benchmark data,
%   - introduce new hypothesis-test families,
%   - analyze failure/deadlock mechanisms,
%   - generate paper figures.
%
% EXPECTED LOCATION
%   results/analysis/analyze_results_section_aux.m
%
% INPUTS (results/analysis/tables)
%   dcta_metric_results.csv
%   publication_condition_pairwise_tests.csv
%   publication_figure_condition_summary.csv
%   figure_clips_post_clue_source.csv
%   figure_maximum_agent_steps_source.csv
%   grid_density_analysis_results.csv
%   grid_density_complete_block_condition_summary.csv
%
% OUTPUTS (results/analysis/tables/results_section_aux)
%   core_primary_max_steps_summary.csv
%   clips_post_clue_summary.csv
%   key_top_pair_support.csv
%   key_full_field_support.csv
%   secondary_metric_summary.csv
%   scale_max_steps_condition_detail.csv
%   scale_max_steps_consistency_summary.csv
%   scale_normalized_omnibus_summary.csv
%   scale_density_direction_summary.csv
%   results_section_aux_report.txt

clear; clc;

scriptDir = string(fileparts(mfilename("fullpath")));
projectRoot = string(fileparts(fileparts(scriptDir)));
tableDir = fullfile(scriptDir, "tables");
outDir = fullfile(tableDir, "results_section_aux");
if ~isfolder(outDir)
    mkdir(outDir);
end

metricPath = fullfile(tableDir, "dcta_metric_results.csv");
pairwisePath = fullfile(tableDir, "publication_condition_pairwise_tests.csv");
publicationFigurePath = fullfile(tableDir, "publication_figure_condition_summary.csv");
postCluePath = fullfile(tableDir, "figure_clips_post_clue_source.csv");
maxStepsPath = fullfile(tableDir, "figure_maximum_agent_steps_source.csv");
scalePath = fullfile(tableDir, "grid_density_analysis_results.csv");
completeBlockScalePath = fullfile(tableDir, ...
    "grid_density_complete_block_condition_summary.csv");

required = [metricPath, pairwisePath, publicationFigurePath, postCluePath, ...
    maxStepsPath, scalePath, completeBlockScalePath];
for i = 1:numel(required)
    if ~isfile(required(i))
        error("Required input is absent: %s", required(i));
    end
end

M = readTextTable(metricPath);
P = readTextTable(pairwisePath);
PF = readTextTable(publicationFigurePath);
PC = readTextTable(postCluePath);
FM = readTextTable(maxStepsPath);
S = readTextTable(scalePath);
CBC = readTextTable(completeBlockScalePath);

algorithmOrder = ["CBAA","ACBBA","PI","HIPC","DMCHBA","DGA"];
algorithmOrderLower = lower(algorithmOrder);
clipsLong = "Clue-Informed Probabilistic Search (CLIPS)";
cvLong = "Collaborative Visit (CV)";

reportPath = fullfile(outDir, "results_section_aux_report.txt");
fid = fopen(reportPath, "w");
if fid < 0
    error("Could not open report for writing: %s", reportPath);
end
cleanup = onCleanup(@() fclose(fid));

logLine(fid, "Revised Results auxiliary analysis");
logLine(fid, "Generated: %s", string(datetime("now")));
logLine(fid, "Purpose: descriptive support for revised Results; no new inferential test family.");
logLine(fid, "All numerical outputs are computed from the repository tables listed below.");
for i = 1:numel(required)
    info = dir(required(i));
    inputTable = readTextTable(required(i));
    relativeInput = replace(extractAfter(required(i), ...
        strlength(projectRoot + filesep)), "\", "/");
    logLine(fid, "INPUT: %s | rows=%d | bytes=%d | modified=%s", ...
        relativeInput, height(inputTable), info.bytes, ...
        string(datetime(info.datenum, "ConvertFrom", "datenum")));
end
logLine(fid, "");

%% ------------------------------------------------------------------------
% 1. Core primary metric: maximum-agent steps across 24 impaired conditions
% -------------------------------------------------------------------------

core = M( ...
    string(M.result_type) == "condition_metric" & ...
    string(M.metric) == "max_agent_steps" & ...
    string(M.comm_model) ~= "ideal" & ...
    ismember(string(M.scenario), [clipsLong, cvLong]), :);

coreRows = {};
detailRows = {};
for scenario = [clipsLong, cvLong]
    Gs = core(string(core.scenario) == scenario, :);

    % Condition identifiers are exact model x nominal-level combinations.
    conditionKey = string(Gs.comm_model) + "|" + string(Gs.comm_level_pct);
    uniqueConditions = unique(conditionKey, "stable");
    assert(numel(uniqueConditions) == 24, ...
        "Expected exactly 24 impaired conditions for %s.", scenario);

    % Add within-condition ranks (lower maximum-agent steps is better).
    for ci = 1:numel(uniqueConditions)
        Gc = Gs(conditionKey == uniqueConditions(ci), :);
        assert(height(Gc) == 6, ...
            "Expected six algorithm rows in core condition %s.", uniqueConditions(ci));

        values = toDouble(Gc.mean_value);
        ranks = tiedrank(values);
        bestValue = min(values);

        for ri = 1:height(Gc)
            detailRows{end+1,1} = table( ... %#ok<SAGROW>
                scenarioShort(scenario), ...
                string(Gc.comm_model(ri)), ...
                toDouble(Gc.comm_level_pct(ri)), ...
                string(Gc.algorithm(ri)), ...
                values(ri), ...
                ranks(ri), ...
                100 * (values(ri) - bestValue) / bestValue, ...
                'VariableNames', { ...
                    'scenario','comm_model','degradation_pct','algorithm', ...
                    'condition_mean_max_agent_steps','condition_rank', ...
                    'percent_above_condition_best'});
        end
    end

    scenarioRows = detailRowsForScenario(detailRows, scenarioShort(scenario));
    D = vertcat(scenarioRows{:});

    for ai = 1:numel(algorithmOrder)
        alg = algorithmOrder(ai);
        Ga = Gs(string(Gs.algorithm) == alg, :);
        assert(height(Ga) == 24, ...
            "Expected 24 impaired metric rows for %s / %s.", scenario, alg);

        Da = D(string(D.algorithm) == alg, :);
        coreRows{end+1,1} = table( ... %#ok<SAGROW>
            scenarioShort(scenario), alg, height(Ga), ...
            mean(toDouble(Ga.mean_value)), ...
            median(toDouble(Ga.mean_value)), ...
            mean(toDouble(Da.condition_rank)), ...
            sum(toDouble(Da.condition_rank) == 1), ...
            sum(toDouble(Da.condition_rank) <= 2), ...
            mean(toDouble(Da.percent_above_condition_best)), ...
            median(toDouble(Da.percent_above_condition_best)), ...
            'VariableNames', { ...
                'scenario','algorithm','impaired_condition_count', ...
                'unweighted_mean_max_agent_steps', ...
                'median_condition_mean_max_agent_steps', ...
                'mean_condition_rank','first_place_condition_count', ...
                'top2_condition_count','mean_percent_above_condition_best', ...
                'median_percent_above_condition_best'});
    end
end

coreSummary = vertcat(coreRows{:});
coreDetail = vertcat(detailRows{:});
coreSummary = sortrows(coreSummary, ["scenario","unweighted_mean_max_agent_steps"]);
writetable(coreSummary, fullfile(outDir, "core_primary_max_steps_summary.csv"));

% Independently reconcile the analysis table against the dedicated maximum-
% agent figure source. No manuscript- or prompt-supplied number is used.
reconcileCoreMaxSteps(core, FM);

logLine(fid, "CORE PRIMARY MAXIMUM-AGENT STEPS");
logTable(fid, coreSummary);
logLine(fid, "");

%% ------------------------------------------------------------------------
% 2. CLIPS post-clue confirmation
% -------------------------------------------------------------------------

post = PC( ...
    string(PC.scenario) == "CLIPS" & ...
    string(PC.comm_model) ~= "ideal", :);

postRows = {};
for ai = 1:numel(algorithmOrder)
    alg = algorithmOrder(ai);
    G = post(string(post.algorithm) == alg, :);
    assert(height(G) == 24, ...
        "Expected 24 impaired post-clue rows for %s.", alg);

    postRows{end+1,1} = table( ... %#ok<SAGROW>
        alg, height(G), mean(toDouble(G.mean)), median(toDouble(G.mean)), ...
        min(toDouble(G.eligible_n)), max(toDouble(G.eligible_n)), ...
        'VariableNames', { ...
            'algorithm','impaired_condition_count', ...
            'unweighted_mean_post_clue_team_steps', ...
            'median_condition_mean_post_clue_team_steps', ...
            'min_condition_eligible_n','max_condition_eligible_n'});
end
postSummary = vertcat(postRows{:});
postSummary = sortrows(postSummary, "unweighted_mean_post_clue_team_steps");
writetable(postSummary, fullfile(outDir, "clips_post_clue_summary.csv"));

reconcilePostClue(post, PF);

logLine(fid, "CLIPS POST-CLUE CONFIRMATION");
logTable(fid, postSummary);
logLine(fid, "");

%% ------------------------------------------------------------------------
% 3. Direct top-pair Holm support across impaired conditions
% -------------------------------------------------------------------------

topPairSpecs = {
    "CLIPS", "max_agent_steps",          "DMCHBA", "ACBBA";
    "CLIPS", "post_clue_steps_to_find",  "DMCHBA", "ACBBA";
    "CV",    "max_agent_steps",          "DGA",     "DMCHBA"
};

pairRows = {};
for si = 1:size(topPairSpecs, 1)
    pairRows{end+1,1} = summarizeDirectPair(P, ... %#ok<SAGROW>
        topPairSpecs{si,1}, topPairSpecs{si,2}, ...
        topPairSpecs{si,3}, topPairSpecs{si,4});
end
topPairSummary = vertcat(pairRows{:});
writetable(topPairSummary, fullfile(outDir, "key_top_pair_support.csv"));

assert(all(topPairSummary.algorithm_1_holm_better + ...
    topPairSummary.algorithm_2_holm_better + ...
    topPairSummary.nonsignificant == ...
    topPairSummary.impaired_condition_count), ...
    "Direct-pair classifications do not reconcile to the source row counts.");

logLine(fid, "KEY DIRECT TOP-PAIR HOLM SUPPORT");
logTable(fid, topPairSummary);
logLine(fid, "");

%% ------------------------------------------------------------------------
% 4. Exceptional full-field support patterns used in prose
% -------------------------------------------------------------------------

fieldSpecs = {
    "CLIPS", "team_messages_per_step", "DMCHBA";
    "CV",    "team_messages_per_step", "DMCHBA";
    "CV",    "total_team_steps",       "HIPC"
};

fieldRows = {};
for si = 1:size(fieldSpecs, 1)
    fieldRows{end+1,1} = summarizeFocalAgainstField(P, ... %#ok<SAGROW>
        fieldSpecs{si,1}, fieldSpecs{si,2}, fieldSpecs{si,3});
end
fieldSupport = vertcat(fieldRows{:});
writetable(fieldSupport, fullfile(outDir, "key_full_field_support.csv"));

assert(all(fieldSupport.focal_holm_better + ...
    fieldSupport.focal_holm_worse + fieldSupport.nonsignificant == ...
    fieldSupport.focal_vs_field_comparison_count), ...
    "Focal-vs-field classifications do not reconcile to the source row counts.");

logLine(fid, "EXCEPTIONAL FULL-FIELD HOLM SUPPORT");
logTable(fid, fieldSupport);
logLine(fid, "");

%% ------------------------------------------------------------------------
% 5. Secondary metrics needed for concise Results prose
% -------------------------------------------------------------------------

secondarySpecs = {
    clipsLong, "total_team_steps";
    clipsLong, "team_messages_per_step";
    clipsLong, "system_cell_revisits";
    cvLong,    "total_team_steps";
    cvLong,    "team_messages_per_step";
    cvLong,    "duplicate_target_visits";
    cvLong,    "unique_cell_contribution_gini";
    cvLong,    "target_completion_gini"
};

secondaryRows = {};
for si = 1:size(secondarySpecs, 1)
    scenario = secondarySpecs{si,1};
    metric = secondarySpecs{si,2};

    G = M( ...
        string(M.scenario) == scenario & ...
        string(M.metric) == metric & ...
        string(M.result_type) == "condition_metric" & ...
        string(M.comm_model) ~= "ideal", :);

    for ai = 1:numel(algorithmOrder)
        alg = algorithmOrder(ai);
        Ga = G(string(G.algorithm) == alg, :);
        assert(height(Ga) == 24, ...
            "Expected 24 impaired rows for %s / %s / %s.", scenario, metric, alg);

        secondaryRows{end+1,1} = table( ... %#ok<SAGROW>
            scenarioShort(scenario), string(metric), alg, ...
            mean(toDouble(Ga.mean_value)), ...
            median(toDouble(Ga.mean_value)), ...
            min(toDouble(Ga.eligible_paired_trials)), ...
            max(toDouble(Ga.eligible_paired_trials)), ...
            string(Ga.units(1)), ...
            'VariableNames', { ...
                'scenario','metric','algorithm', ...
                'unweighted_mean_across_24_impaired_conditions', ...
                'median_condition_mean', ...
                'min_condition_eligible_n','max_condition_eligible_n','units'});
    end
end
secondarySummary = vertcat(secondaryRows{:});
writetable(secondarySummary, fullfile(outDir, "secondary_metric_summary.csv"));

logLine(fid, "SECONDARY METRIC SUMMARY");
logTable(fid, secondarySummary);
logLine(fid, "");

%% ------------------------------------------------------------------------
% 6. Scale-study consistency of the PRIMARY max-agent metric
%    Descriptive only: no new hypothesis tests.
% -------------------------------------------------------------------------

% The original all-mission analysis table has independently eligible rows.
% Use the raw-data complete-block source for every maximum-agent-step value
% and rank so a failure of any one algorithm excludes its full trial block.
scaleMax = CBC(ismember(string(CBC.scenario), ["CLIPS", "CV"]), :);
scaleMax.mission = repmat("", height(scaleMax), 1);
scaleMax.mission(string(scaleMax.scenario) == "CLIPS") = ...
    "Clue-Informed Probabilistic Search (CLIPS)";
scaleMax.mission(string(scaleMax.scenario) == "CV") = ...
    "Collaborative Visit (CV)";
scaleMax.mean = toDouble(scaleMax.condition_mean_max_agent_steps);
scaleMax.attempted_n = toDouble(scaleMax.attempted_block_n);
scaleMax.completed_n = toDouble(scaleMax.raw_completed_n);
scaleMax.eligible_n = toDouble(scaleMax.common_block_eligible_n);
scaleMax.failed_n = toDouble(scaleMax.raw_failed_n);
scaleMax.algorithm_key = lower(string(scaleMax.algorithm));

scaleDetailRows = {};
scaleSummaryRows = {};
for missionKey = ["CLIPS","CV"]
    if missionKey == "CLIPS"
        Gm = scaleMax(contains(string(scaleMax.mission), "CLIPS"), :);
    else
        Gm = scaleMax(contains(string(scaleMax.mission), "Collaborative Visit"), :);
    end

    grids = sort(unique(toDouble(Gm.grid_size)))';
    densities = sort(unique(toDouble(Gm.target_cells_per_robot)))';
    comms = unique(string(Gm.comm_label), "stable");

    expectedConditions = numel(grids) * numel(densities) * numel(comms);
    assert(expectedConditions == 32, ...
        "Expected 32 scale conditions per mission.");

    for gi = 1:numel(grids)
        for di = 1:numel(densities)
            for ci = 1:numel(comms)
                Gc = Gm( ...
                    toDouble(Gm.grid_size) == grids(gi) & ...
                    toDouble(Gm.target_cells_per_robot) == densities(di) & ...
                    string(Gm.comm_label) == comms(ci), :);

                assert(height(Gc) == 6, ...
                    "Expected six algorithms in scale condition %s g=%g d=%g %s.", ...
                    missionKey, grids(gi), densities(di), comms(ci));

                means = toDouble(Gc.mean);
                ranks = tiedrank(means);
                best = min(means);

                for ri = 1:height(Gc)
                    scaleDetailRows{end+1,1} = table( ... %#ok<SAGROW>
                        missionKey, grids(gi), densities(di), ...
                        toDouble(Gc.robot_count(ri)), string(comms(ci)), ...
                        upper(string(Gc.algorithm_key(ri))), ...
                        means(ri), ranks(ri), ...
                        100 * (means(ri) - best) / best, ...
                        toDouble(Gc.attempted_n(ri)), ...
                        toDouble(Gc.completed_n(ri)), ...
                        toDouble(Gc.eligible_n(ri)), ...
                        toDouble(Gc.failed_n(ri)), ...
                        'VariableNames', { ...
                            'scenario','grid_size','target_cells_per_robot', ...
                            'robot_count','comm_label','algorithm', ...
                            'mean_max_agent_steps','condition_rank', ...
                            'percent_above_condition_best', ...
                            'attempted_n','completed_n','eligible_n','failed_n'});
                end
            end
        end
    end

    missionRows = scaleDetailRowsForMission(scaleDetailRows, missionKey);
    Dm = vertcat(missionRows{:});
    for ai = 1:numel(algorithmOrder)
        alg = algorithmOrder(ai);
        Ga = Dm(string(Dm.algorithm) == alg, :);
        assert(height(Ga) == 32, ...
            "Expected 32 scale-condition rows for %s / %s.", missionKey, alg);

        scaleSummaryRows{end+1,1} = table( ... %#ok<SAGROW>
            missionKey, alg, height(Ga), ...
            mean(toDouble(Ga.condition_rank)), ...
            median(toDouble(Ga.condition_rank)), ...
            sum(toDouble(Ga.condition_rank) == 1), ...
            sum(toDouble(Ga.condition_rank) <= 2), ...
            mean(toDouble(Ga.percent_above_condition_best)), ...
            median(toDouble(Ga.percent_above_condition_best)), ...
            sum(toDouble(Ga.attempted_n)), ...
            sum(toDouble(Ga.completed_n)), ...
            sum(toDouble(Ga.eligible_n)), ...
            sum(toDouble(Ga.failed_n)), ...
            'VariableNames', { ...
                'scenario','algorithm','scale_condition_count', ...
                'mean_condition_rank','median_condition_rank', ...
                'first_place_condition_count','top2_condition_count', ...
                'mean_percent_above_condition_best', ...
                'median_percent_above_condition_best', ...
                'attempted_n_total','completed_n_total', ...
                'eligible_n_total','failed_n_total'});
    end
end

scaleDetail = vertcat(scaleDetailRows{:});
scaleConsistency = vertcat(scaleSummaryRows{:});
scaleConsistency = sortrows(scaleConsistency, ["scenario","mean_condition_rank"]);

writetable(scaleDetail, fullfile(outDir, "scale_max_steps_condition_detail.csv"));
writetable(scaleConsistency, fullfile(outDir, "scale_max_steps_consistency_summary.csv"));

logLine(fid, "SCALE-STUDY PRIMARY MAX-STEP CONSISTENCY (DESCRIPTIVE)");
logLine(fid, "First-place/top-2 counts and mean rank are descriptive summaries only.");
logTable(fid, scaleConsistency);
logLine(fid, "");

%% ------------------------------------------------------------------------
% 7. Existing normalized-primary scale omnibus counts
% -------------------------------------------------------------------------

omnibusRows = {};
for missionKey = ["CLIPS","CV"]
    for type = ["grid_size_omnibus","density_omnibus"]
        if missionKey == "CLIPS"
            G = S( ...
                string(S.table_type) == type & ...
                string(S.metric_key) == "normalized_primary" & ...
                contains(string(S.mission), "CLIPS"), :);
        else
            G = S( ...
                string(S.table_type) == type & ...
                string(S.metric_key) == "normalized_primary" & ...
                contains(string(S.mission), "Collaborative Visit"), :);
        end

        assert(height(G) == 48, ...
            "Expected 48 normalized-primary omnibus families for %s / %s.", ...
            missionKey, type);

        omnibusRows{end+1,1} = table( ... %#ok<SAGROW>
            missionKey, type, height(G), ...
            sum(toLogical(G.reject_0_05)), ...
            'VariableNames', { ...
                'scenario','analysis_family','family_count', ...
                'significant_family_count'});
    end
end

omnibusSummary = vertcat(omnibusRows{:});
writetable(omnibusSummary, fullfile(outDir, "scale_normalized_omnibus_summary.csv"));

assert(all(omnibusSummary.significant_family_count >= 0 & ...
    omnibusSummary.significant_family_count <= omnibusSummary.family_count), ...
    "Invalid normalized-primary omnibus counts.");

logLine(fid, "SCALE NORMALIZED-PRIMARY OMNIBUS COUNTS");
logTable(fid, omnibusSummary);
logLine(fid, "");

%% ------------------------------------------------------------------------
% 8. Existing CV density post-hoc direction summary
% -------------------------------------------------------------------------

densityTests = S( ...
    string(S.table_type) == "density_pairwise_tests" & ...
    string(S.metric_key) == "normalized_primary" & ...
    contains(string(S.mission), "Collaborative Visit"), :);

directionRows = {};
for ai = 1:numel(algorithmOrder)
    algLower = algorithmOrderLower(ai);
    G = densityTests(string(densityTests.algorithm_key) == algLower, :);
    significant = toLogical(G.reject_holm_0_05);
    Gs = G(significant, :);

    % target_cells_per_robot increases from level_a to level_b.
    % Higher cells/robot = FEWER robots.
    % mean_delta_level_b_minus_a < 0 => fewer robots had lower/better metric.
    deltas = toDouble(Gs.mean_delta_level_b_minus_a);
    favorsFewer = sum(deltas < 0);
    favorsMore = sum(deltas > 0);
    ties = sum(deltas == 0);

    directionRows{end+1,1} = table( ... %#ok<SAGROW>
        algorithmOrder(ai), height(G), height(Gs), ...
        favorsFewer, favorsMore, ties, ...
        'VariableNames', { ...
            'algorithm','tested_density_pairwise_comparisons', ...
            'holm_significant_comparisons', ...
            'significant_favoring_fewer_robots', ...
            'significant_favoring_more_robots', ...
            'significant_zero_direction'});
end

densityDirection = vertcat(directionRows{:});
writetable(densityDirection, fullfile(outDir, "scale_density_direction_summary.csv"));

logLine(fid, "CV DENSITY DIRECTION SUMMARY");
logTable(fid, densityDirection);
logLine(fid, "");

%% ------------------------------------------------------------------------
% Final
% -------------------------------------------------------------------------

logLine(fid, "PASS");
logLine(fid, "All auxiliary summaries generated without modifying source data.");
fprintf("PASS: auxiliary Results summaries written to:\n  %s\n", outDir);
fprintf("Report:\n  %s\n", reportPath);

%% ========================================================================
% Local helpers
% ========================================================================

function T = readTextTable(path)
    opts = detectImportOptions(path, "Delimiter", ",", "TextType", "string", ...
        "VariableNamingRule", "preserve");
    opts.DataLines = [2 Inf];
    T = readtable(path, opts);
end

function x = toDouble(x)
    if isnumeric(x) || islogical(x)
        x = double(x);
    else
        x = str2double(string(x));
    end
end

function x = toLogical(x)
    if islogical(x)
        return;
    end
    if isnumeric(x)
        x = x ~= 0;
        return;
    end
    s = lower(strtrim(string(x)));
    x = s == "true" | s == "1" | s == "yes";
end

function short = scenarioShort(long)
    if contains(string(long), "CLIPS")
        short = "CLIPS";
    elseif contains(string(long), "Collaborative Visit")
        short = "CV";
    else
        error("Unknown scenario: %s", long);
    end
end

function rows = detailRowsForScenario(allRows, shortScenario)
    rows = {};
    for i = 1:numel(allRows)
        if allRows{i}.scenario == shortScenario
            rows{end+1,1} = allRows{i}; %#ok<AGROW>
        end
    end
end

function rows = scaleDetailRowsForMission(allRows, missionKey)
    rows = {};
    for i = 1:numel(allRows)
        if allRows{i}.scenario == missionKey
            rows{end+1,1} = allRows{i}; %#ok<AGROW>
        end
    end
end

function row = summarizeDirectPair(P, scenario, metric, algorithm1, algorithm2)
    mask = ...
        string(P.scenario) == scenario & ...
        string(P.metric) == metric & ...
        toDouble(P.degradation_pct) > 0 & ...
        ( ...
            (string(P.algorithm_a) == algorithm1 & string(P.algorithm_b) == algorithm2) | ...
            (string(P.algorithm_a) == algorithm2 & string(P.algorithm_b) == algorithm1) ...
        );
    G = P(mask, :);
    assert(height(G) == 24, ...
        "Expected 24 impaired direct-pair conditions for %s/%s/%s-%s.", ...
        scenario, metric, algorithm1, algorithm2);

    significant = toLogical(G.reject_holm_0_05);
    a1Better = 0;
    a2Better = 0;
    nonsig = sum(~significant);

    for i = 1:height(G)
        if ~significant(i)
            continue;
        end
        meanA = toDouble(G.algorithm_a_mean(i));
        meanB = toDouble(G.algorithm_b_mean(i));
        if meanA < meanB
            winner = string(G.algorithm_a(i));
        elseif meanB < meanA
            winner = string(G.algorithm_b(i));
        else
            winner = "";
        end

        if winner == algorithm1
            a1Better = a1Better + 1;
        elseif winner == algorithm2
            a2Better = a2Better + 1;
        end
    end

    row = table( ...
        string(scenario), string(metric), string(algorithm1), string(algorithm2), ...
        height(G), a1Better, a2Better, nonsig, ...
        'VariableNames', { ...
            'scenario','metric','algorithm_1','algorithm_2', ...
            'impaired_condition_count','algorithm_1_holm_better', ...
            'algorithm_2_holm_better','nonsignificant'});
end

function row = summarizeFocalAgainstField(P, scenario, metric, focal)
    mask = ...
        string(P.scenario) == scenario & ...
        string(P.metric) == metric & ...
        toDouble(P.degradation_pct) > 0 & ...
        (string(P.algorithm_a) == focal | string(P.algorithm_b) == focal);
    G = P(mask, :);
    assert(height(G) == 120, ...
        "Expected 120 focal-vs-field comparisons for %s/%s/%s.", ...
        scenario, metric, focal);

    significant = toLogical(G.reject_holm_0_05);
    better = 0;
    worse = 0;
    nonsig = sum(~significant);

    for i = 1:height(G)
        if ~significant(i)
            continue;
        end
        meanA = toDouble(G.algorithm_a_mean(i));
        meanB = toDouble(G.algorithm_b_mean(i));
        if meanA < meanB
            winner = string(G.algorithm_a(i));
        elseif meanB < meanA
            winner = string(G.algorithm_b(i));
        else
            winner = "";
        end

        if winner == focal
            better = better + 1;
        else
            worse = worse + 1;
        end
    end

    row = table( ...
        string(scenario), string(metric), string(focal), ...
        height(G), better, worse, nonsig, ...
        'VariableNames', { ...
            'scenario','metric','focal_algorithm', ...
            'focal_vs_field_comparison_count','focal_holm_better', ...
            'focal_holm_worse','nonsignificant'});
end

function reconcileCoreMaxSteps(core, FM)
    F = FM(ismember(string(FM.scenario), ["CLIPS","CV"]) & ...
        string(FM.metric) == "max_agent_steps" & ...
        string(FM.comm_model) ~= "ideal", :);
    assert(height(core) == 288 && height(F) == 288, ...
        "Expected 288 CLIPS/CV impaired maximum-agent rows in both sources.");
    for i = 1:height(core)
        shortScenario = scenarioShort(core.scenario(i));
        match = string(F.scenario) == shortScenario & ...
            string(F.comm_model) == string(core.comm_model(i)) & ...
            toDouble(F.degradation_pct) == toDouble(core.comm_level_pct(i)) & ...
            string(F.algorithm) == string(core.algorithm(i));
        assert(sum(match) == 1, "Maximum-agent reconciliation key is not unique.");
        assert(abs(toDouble(F.mean(match)) - toDouble(core.mean_value(i))) <= 1e-10, ...
            "Maximum-agent means disagree between authoritative tables.");
        assert(toDouble(F.eligible_n(match)) == toDouble(core.eligible_paired_trials(i)), ...
            "Maximum-agent eligible counts disagree between authoritative tables.");
    end
end

function reconcilePostClue(post, PF)
    source = PF(string(PF.scenario) == "CLIPS" & ...
        string(PF.metric) == "post_clue_steps_to_find" & ...
        string(PF.comm_model) ~= "ideal", :);
    assert(height(post) == 144 && height(source) == 144, ...
        "Expected 144 CLIPS impaired post-clue rows in both sources.");
    for i = 1:height(post)
        match = string(source.comm_model) == string(post.comm_model(i)) & ...
            toDouble(source.degradation_pct) == toDouble(post.degradation_pct(i)) & ...
            string(source.algorithm) == string(post.algorithm(i));
        assert(sum(match) == 1, "Post-clue reconciliation key is not unique.");
        assert(abs(toDouble(source.mean(match)) - toDouble(post.mean(i))) <= 1e-10, ...
            "Post-clue means disagree between authoritative tables.");
        assert(toDouble(source.eligible_n(match)) == toDouble(post.eligible_n(i)), ...
            "Post-clue eligible counts disagree between authoritative tables.");
    end
end

function logLine(fid, fmt, varargin)
    fprintf(fid, [char(string(fmt)) '\n'], varargin{:});
end

function logTable(fid, T)
    old = evalc("disp(T)");
    old = regexprep(old, '</?strong>', '');
    old = regexprep(old, '[ \t]+(\r?\n)', '$1');
    old = regexprep(old, '(\r?\n)+$', '');
    fprintf(fid, "%s\n", old);
end
